#!/usr/bin/env python3
"""Validate an ICS file: structure, required fields, and date ordering.

Usage: validate_ics.py <file.ics>
Uses the icalendar library when available; otherwise falls back to
structural regex checks.
"""
import re
import sys
from datetime import datetime

try:
    from icalendar import Calendar
    HAVE_ICAL = True
except ImportError:
    HAVE_ICAL = False


def parse_dt(value):
    value = value.strip()
    if len(value) == 8 and value.isdigit():
        return datetime.strptime(value, "%Y%m%d")
    if value.endswith("Z"):
        return datetime.strptime(value, "%Y%m%dT%H%M%SZ")
    try:
        return datetime.strptime(value, "%Y%m%dT%H%M%S%z")
    except ValueError:
        return datetime.strptime(value, "%Y%m%dT%H%M%S")


def validate_with_library(path):
    """Parse with icalendar and check required fields."""
    with open(path, "rb") as f:
        cal = Calendar.from_ical(f.read())
    errors = []
    events = [c for c in cal.walk() if c.name == "VEVENT"]
    if not events:
        errors.append("No VEVENT components found")
    for ev in events:
        if ev.get("uid") is None:
            errors.append("VEVENT missing UID")
        if ev.get("dtstamp") is None:
            errors.append("VEVENT missing DTSTAMP")
        if ev.get("summary") is None:
            errors.append("VEVENT missing SUMMARY")
        start = ev.get("dtstart")
        end = ev.get("dtend")
        if start is None:
            errors.append("VEVENT missing DTSTART")
        if start is not None and end is not None:
            try:
                if end.dt <= start.dt:
                    errors.append("DTEND must be after DTSTART")
            except TypeError:
                pass  # naive vs aware comparison not possible; skip
        if start is not None and end is None and ev.get("duration") is None:
            errors.append("VEVENT has neither DTEND nor DURATION")
    if errors:
        print("INVALID")
        for e in errors:
            print(" -", e)
        sys.exit(1)
    print("VALID (parsed with icalendar library)")
    for ev in events:
        print(" Summary:", ev.get("summary"))
        print(" Start:  ", ev.get("dtstart").dt)
        print(" End:    ", ev.get("dtend").dt if ev.get("dtend") else ev.get("duration"))
        print(" UID:    ", ev.get("uid"))
        print(" DTSTAMP:", ev.get("dtstamp").dt)


def validate_manually(path):
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    errors, warnings = [], []
    if "BEGIN:VCALENDAR" not in text:
        errors.append("Missing BEGIN:VCALENDAR")
    if "END:VCALENDAR" not in text:
        errors.append("Missing END:VCALENDAR")
    if "VERSION:2.0" not in text:
        errors.append("Missing VERSION:2.0")
    if "PRODID" not in text:
        warnings.append("Missing PRODID")
    for m in re.finditer(r"BEGIN:VEVENT(.*?)END:VEVENT", text, re.S):
        body = m.group(1)
        for field in ("SUMMARY", "UID", "DTSTAMP", "DTSTART"):
            if not re.search(rf"(?m)^{field}(;[^:]*)?:", body):
                errors.append(f"VEVENT missing {field}")
        s = re.search(r"(?m)^DTSTART(;[^:]*)?:(.*)$", body)
        e = re.search(r"(?m)^DTEND(;[^:]*)?:(.*)$", body)
        if s and e:
            try:
                start = parse_dt(s.group(2))
                end = parse_dt(e.group(2))
                if end <= start:
                    errors.append("DTEND must be after DTSTART")
            except ValueError as exc:
                errors.append(f"Date parse error: {exc}")
        elif s and not e and "DURATION" not in body:
            warnings.append("VEVENT has neither DTEND nor DURATION")
    if errors:
        print("INVALID")
        for e in errors:
            print(" -", e)
        sys.exit(1)
    print("VALID (structural checks; icalendar library not available)")
    for w in warnings:
        print(" *", w)
    s = re.search(r"(?m)^SUMMARY:(.*)$", text)
    if s:
        print(" Summary:", s.group(1).strip())
    dt = re.search(r"(?m)^DTSTART(;[^:]*)?:(.*)$", text)
    de = re.search(r"(?m)^DTEND(;[^:]*)?:(.*)$", text)
    if dt and de:
        print(" Start:  ", dt.group(2))
        print(" End:    ", de.group(2))


def main():
    if len(sys.argv) < 2:
        sys.exit("usage: validate_ics.py <file.ics>")
    path = sys.argv[1]
    if HAVE_ICAL:
        validate_with_library(path)
    else:
        validate_manually(path)


if __name__ == "__main__":
    main()

